import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"Week 7 — Measuring Test Adequacy","description":"","frontmatter":{"source":"weeks/07-test-adequacy/README.md"},"headers":[],"relativePath":"weeks/07-test-adequacy/index.md","filePath":"weeks/07-test-adequacy/index.md"}'),s={name:"weeks/07-test-adequacy/index.md"};function n(i,e,d,h,l,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="week-7--measuring-test-adequacy" tabindex="-1">Week 7 — Measuring Test Adequacy <a class="header-anchor" href="#week-7--measuring-test-adequacy" aria-label="Permalink to &quot;Week 7 — Measuring Test Adequacy&quot;">​</a></h1><blockquote><p>Coverage tells you which code your tests ran; mutation testing tells you which mistakes they would notice. Neither tells you the code was right to begin with.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before the Seminar</strong></td><td>Read the reading and post your reading response on Canvas · submit the week 6 assignment (the Seminar opens with its quiz) · if a graduate paper is presented, post one question about it (<a href="./../../graduate/paper-presentations.html#questions-from-the-class">how</a>)</td></tr><tr><td><strong>Seminar</strong></td><td>Due-date quiz on your property suite and bug reports (7 min, 🔴 AI off) · talk (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-07.html" target="_blank" rel="noreferrer">slides</a>) · reading discussion and a short debate, or a graduate presentation · demo: a mutant that looks equivalent, killed by a biased property · Lab preview</td></tr><tr><td><strong>Lab</strong></td><td><a href="./lab.html#lab--what-would-your-tests-notice-75-min">Mutation testing</a> of <code>roomly</code> with StrykerJS: read the report, compare the shipped tests, an agent-written batch and your week 6 properties on one module, and triage the survivors. <strong>Checkoff:</strong> three survivors triaged with reasons</td></tr><tr><td><strong>Due before next week&#39;s Seminar</strong></td><td>Default 11:59 pm the night before: the <a href="./lab.html#assignment--raise-a-modules-mutation-score-honestly">assignment</a>: raise one module&#39;s mutation score with tests whose assertions you can justify, and report, including an agent-written batch against your own</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: running StrykerJS, the agent&#39;s test batch, your tests (Safe Loop) · 🟡 AI limited: the report (yours; numbers from the tools) · 🔴 AI off: the quiz, the reading response, and every triage decision</td></tr><tr><td><strong>Reading</strong></td><td>Foster, Gulati, Harman et al. (Meta), <a href="https://arxiv.org/abs/2501.12862" target="_blank" rel="noreferrer">&quot;Mutation-Guided LLM-based Test Generation at Meta&quot;</a> (FSE 2025 Industry)</td></tr><tr><td><strong>Reading response</strong></td><td>150–250 words on Canvas, 🔴 AI off, before the Seminar (prompt <a href="#reading">below</a>)</td></tr><tr><td><strong>Team project</strong></td><td>M1 (each member&#39;s first PR, reviewed, CI green) is due before the week 9 Seminar (<a href="./../../project/milestones.html#m1-first-pr">milestones</a>). Record a baseline mutation score for the module your M1 PR touches, with StrykerJS or mutmut (<a href="./../../TOOLS.html#tools-by-week">Tool Handout: Tools by week</a>); M2 asks for it</td></tr><tr><td><strong>Graduate track</strong></td><td>Foster et al. and Zhao, Zhou &amp; Cohen are this week&#39;s seminar papers. The Zhao study is on the <a href="./../../resources/reading-list.html#replicable-studies">replicable list</a></td></tr><tr><td><strong>Time</strong></td><td>Meetings 2.5 h · outside about 6 h (CS [5xxx]: about 7.5 h): reading and response 45 min, assignment about 3.5 h, team project about 1.75 h</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Explain the difference between coverage and <a href="./../../resources/glossary.html#mutation-score">mutation score</a>, and compute StrykerJS&#39;s two scores from a report.</li><li>Run StrykerJS on a module or a line range with chosen test files, reproducibly.</li><li>Read mutation operators and statuses: killed, survived, no coverage, timeout, error, ignored.</li><li>Triage a surviving mutant: kill it with a justified test, argue that it&#39;s an <a href="./../../resources/glossary.html#equivalent-mutant">equivalent mutant</a>, or recognize a real bug.</li><li>Compare suites, including an agent-written one, by mutation score on the same code, and say what the score can&#39;t show.</li><li>Raise a module&#39;s score without gaming it.</li></ol><h2 id="seminar" tabindex="-1">Seminar <a class="header-anchor" href="#seminar" aria-label="Permalink to &quot;Seminar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Block</th><th>Minutes</th><th>What happens</th></tr></thead><tbody><tr><td>Due-date quiz</td><td>7</td><td>On your week 6 assignment (<a href="./../../assessment/quizzes.html">quizzes</a>), 🔴 AI off</td></tr><tr><td>Concept talk</td><td>25</td><td>Coverage vs mutation score; operators; equivalent mutants; mutation-guided generation; the ISSTA 2026 caveat (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-07.html" target="_blank" rel="noreferrer">slides</a>)</td></tr><tr><td>Discussion and debate</td><td>20</td><td>The reading, then &quot;Should our CI fail a PR whose mutation score drops?&quot; (or a graduate presentation)</td></tr><tr><td>Live demo</td><td>10</td><td>StrykerJS on <code>roomly</code>&#39;s <code>time.js</code>: a survivor that looks equivalent isn&#39;t</td></tr><tr><td>Lab preview</td><td>5</td><td>Node 22; run the baseline before the Lab; the checkoff</td></tr></tbody></table><p>The evidence: suites with 100% coverage can have a 4% mutation score (<a href="https://arxiv.org/html/2506.02954v5" target="_blank" rel="noreferrer">MutGen</a>, preprint). Meta&#39;s ACH generated 9,095 mutants representing a concern (privacy) and 571 tests to kill them; its equivalent-mutant detector reached 0.95 precision and 0.96 recall, and engineers accepted 73% of the tests (<a href="https://arxiv.org/abs/2501.12862" target="_blank" rel="noreferrer">Foster et al.</a>). LLM-generated mutants detected 87.98% of 851 real bugs against 41.64% for rule-based ones, at the cost of more mutants that don&#39;t compile or are equivalent (<a href="https://arxiv.org/abs/2406.09843" target="_blank" rel="noreferrer">Wang et al.</a>, preprint). And the caveat: for LLM-generated suites, coverage and mutation score track bug-finding in regression settings but are unreliable when the code may already be buggy (<a href="https://arxiv.org/abs/2607.22880" target="_blank" rel="noreferrer">Zhao, Zhou &amp; Cohen</a>, ISSTA 2026), which is the usual situation for AI-written code.</p><h2 id="lab" tabindex="-1">Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;Lab&quot;">​</a></h2><p>The <a href="./lab.html#lab--what-would-your-tests-notice-75-min">lab</a> runs StrykerJS on the <a href="https://github.com/Boyu-Zhang-UOI/eswa-roomly" target="_blank" rel="noreferrer"><code>roomly</code> kit</a> from your week 6 <code>fixes</code> branch, where every test passes (Stryker refuses to start otherwise). You measure three suites on the same code: the shipped tests, a batch an agent writes in the Lab, and your week 6 properties. Then you triage survivors by hand: write a test that kills one, argue that one can&#39;t be killed, or notice that the mutant does what the Booking rules say and the code doesn&#39;t. The <a href="./lab.html#assignment--raise-a-modules-mutation-score-honestly">assignment</a> raises one module&#39;s score, with every assertion justified.</p><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><p><strong>Foster, Gulati, Harman et al., <a href="https://arxiv.org/abs/2501.12862" target="_blank" rel="noreferrer">&quot;Mutation-Guided LLM-based Test Generation at Meta&quot;</a></strong> (FSE 2025 Industry). Instead of generating tests for coverage, ACH generates mutants that represent one concern, then tests that kill them, and an LLM filters out equivalent mutants. Read the abstract, the system overview, and the deployment results.</p><p><strong>Reading response prompt</strong> (150–250 words, 🔴 AI off, on Canvas): State ACH&#39;s main idea and two of its numbers. Why generate mutants for one concern instead of all of them? What does &quot;engineers accepted 73% of the tests&quot; measure, and what doesn&#39;t it? Then pick one Booking rule in <code>roomly</code> you&#39;d treat as a concern, and describe one mutant that represents a violation of it. End with one question for the Seminar.</p><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><ul><li><strong>Coverage is &quot;ran&quot;, mutation is &quot;noticed&quot;.</strong> A line can run under a test that asserts nothing about it (<a href="./../../resources/glossary.html#mutation-testing">mutation testing</a>).</li><li><strong>A mutant is a plausible mistake.</strong> <code>&lt;</code> becomes <code>&lt;=</code>, a condition becomes <code>true</code>, a block becomes empty. A failing test <em>kills</em> it; if every test passes, it <em>survives</em>; if no test runs it, it has <em>no coverage</em>.</li><li><strong>Two scores.</strong> StrykerJS reports detected ÷ valid mutants (total) and detected ÷ covered valid mutants (covered). Mutants that crash the code or are ignored don&#39;t count.</li><li><strong>A survivor is a question, not a to-do.</strong> Either a test is missing an assertion (kill it), no input can tell the difference (equivalent: argue it), or the mutant matches the spec better than the code does (a real bug). Some are &quot;nearly equivalent&quot;: they differ only on rare inputs, which biased generators reach.</li><li><strong>Scores can be gamed.</strong> Tests without assertions, tests that assert a detail only because the mutant changes it, disabled mutants, a narrowed scope. Every assertion should trace to a rule.</li><li><strong>The caveat.</strong> Mutation score measures how well tests pin the code&#39;s current behavior. When that behavior may be wrong, a high score can mean tests that agree with the bugs.</li></ul><h2 id="check-your-understanding" tabindex="-1">Check your understanding <a class="header-anchor" href="#check-your-understanding" aria-label="Permalink to &quot;Check your understanding&quot;">​</a></h2><ol><li>A suite covers every line of <code>overlaps()</code>, yet the mutant <code>aStart &gt; bStart</code> → <code>aStart &gt;= bStart</code> survives. What does that tell you, and what&#39;s your next step?</li><li>A report shows 68 killed, 0 timeouts, 67 survived, 17 no coverage and 3 runtime errors. Compute both scores.</li><li>Why does calling a mutant equivalent need an argument rather than another run?</li><li>A test kills a mutant only by asserting an error message&#39;s exact wording. Keep it or not? What decides?</li><li>How could an agent-written batch raise the mutation score of buggy code while making the bugs harder to fix?</li></ol><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>StrykerJS needs Node 22.</strong> In a Codespace: <code>nvm install 22 &amp;&amp; nvm use 22</code>, then <code>npm install</code> again.</li><li><strong>Too slow:</strong> mutate a line range (<code>--mutate &quot;src/bookingService.js:176-253&quot;</code>) instead of the whole project.</li><li><strong>The tap runner misbehaves:</strong> use the command runner from <code>roomly</code>&#39;s README; it&#39;s slower and has no per-test coverage.</li><li><strong>No StrykerJS at all:</strong> mutate by hand in a scratch copy: apply five mutants with an editor, run the tests after each, and record which survive. That&#39;s all a mutation tool does, slowly.</li><li><strong>The agent is down:</strong> staff post a saved agent-written batch for the Lab.</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Zhao, Zhou &amp; Cohen, <a href="https://arxiv.org/abs/2607.22880" target="_blank" rel="noreferrer">&quot;Do Coverage and Mutation Scores of LLM-Generated Test Suites Correlate with Their Effectiveness?&quot;</a>: the caveat in full, and a <a href="./../../graduate/empirical-study.html">graduate study</a> to replicate.</li><li>Wang et al., <a href="https://arxiv.org/abs/2406.09843" target="_blank" rel="noreferrer">&quot;A Comprehensive Study on Large Language Models for Mutation Testing&quot;</a>.</li><li>Previous week: <a href="./../06-tests-as-oracles/">Tests as Oracles</a>. Next week: <a href="./../08-legacy-code/">Legacy Code</a>, where the mutation score helps prove a refactor changed nothing.</li></ul>',23)])])}const m=t(s,[["render",n]]);export{g as __pageData,m as default};
